#!/usr/bin/env python3
"""Rebuild the offline canyon comparison report from saved native captures/logs."""
from pathlib import Path
import re,json,statistics,os
os.chdir(Path(__file__).resolve().parents[1])
r=Path('docs/reports/canyon-terraces')
parse=lambda p:dict(re.findall(r'(\w+)=([^\s]+)',p.read_text().split('BENCHMARK ')[-1]))
bench={mode:[parse(r/f'{prefix}-{i}.log') for i in range(1,4) if (r/f'{prefix}-{i}.log').exists() and 'BENCHMARK ' in (r/f'{prefix}-{i}.log').read_text()] for mode,prefix in [('legacy','paired-legacy'),('terraced','after-benchmark')]}
assert all(len(v)==3 for v in bench.values()), 'Need three completed paired runs per mode'
assert all('PASS' in (r/p).read_text() and 'FAIL:' not in (r/p).read_text() for p in ['geometry-tests.log','graphics-assets-tests.log','occlusion-tests.log'])
invariants=['seed','resolution','frames','max_projectiles','min_active_enemies','min_active_projectiles','kills','max_chain_depth','suppressed']
assert all(len({run[k] for runs in bench.values() for run in runs})==1 for k in invariants), 'Stress workloads must match'
g=re.search(r'GEOMETRY (.*)',(r/'geometry-tests.log').read_text()).group(1)
geometry=dict(re.findall(r'(\w+)=([^\s]+)',g))
fields=['mean_ms','p95_ms','max_ms','simulation_ms','draw_ms','present_ms']
stats={mode:{k:statistics.median(float(v[k]) for v in runs) for k in fields} for mode,runs in bench.items() if runs}
data={'base_commit':'7e565fe','seed':1866,'capture':{'resolution':[1440,900],'zoom_percent':160,'projection':'perspective','fov':45,'frames':120,'style':'original','scenes':['combat','profile-quarry','profile-works']},'geometry':geometry,'rollback_comparison':{'resolution':[1440,900],'maximum_channel_delta_excluding_fps':2,'changed_channel_fraction_excluding_fps':0.00034722222222222224},'benchmark_runs':bench,'benchmark_medians':stats,'benchmark_note':'Uncapped stress workload, 240 frames, not ordinary gameplay FPS. Alternating legacy/default in the same final executable; no parallel graphics jobs.','checks':{'geometry':'PASS','gameplay_suites':5,'gameplay':'PASS','western_assets':'PASS','occlusion_and_aim':'PASS','WASM':'not run, standing user waiver'}}
(r/'measurements.json').write_text(json.dumps(data,indent=2)+'\n')
cards=''
for name,label in [('combat','Trail and combat room'),('quarry','Quarry floor identity'),('works','Railroad works floor identity')]:
 cards+=f'''<article><h3>{label}</h3><div class="compare" style="--split:50%"><img src="after-{name}.png" alt="Lower terraced canyon, {label}" width="1440" height="900"><div class="before"><img src="before-{name}.png" alt="Original canyon, {label}" width="1440" height="900"></div><span class="old">Original</span><span class="new">Terraced</span><div class="divider"></div></div><label class="slider">Original / terraced <input aria-label="Compare {label}" type="range" min="0" max="100" value="50"></label><p><a href="before-{name}.png">Original PNG</a> · <a href="after-{name}.png">New PNG</a> · <a href="after-{name}.log">Capture log</a></p></article>'''
rows=''
if len(stats)==2:
 for k in fields:
  a,b=stats['legacy'][k],stats['terraced'][k]
  rows+=f'<tr><td>{k}</td><td>{a:.3f}</td><td>{b:.3f}</td><td>{(b/a-1)*100:+.1f}%</td></tr>'
else:rows='<tr><td colspan="4">Paired measurements pending.</td></tr>'
config=[]
for line in Path('assets/visual/canyon.cfg').read_text().splitlines():
 if line and not line.startswith('#') and not line.startswith('DEATHWARD'):config.append(line.split())
explanations={
'enabled':'0 restores the original surface and original decoration paths; 1 enables this treatment.',
'minimum_height':'Minimum local highland cap in metres, not minimum shelf elevation. Valid 0.8–10.',
'maximum_height':'Maximum local highland cap in metres, bounded by original height; valid minimum_height–16. Existing low cover keeps 93% of original height.',
'height_variation':'Broad seeded cap variation, 0–1. Rare coherent highland peaks.',
'terrace_count':'1–6 shelves in the distance-to-floor profile. Existing rock extent limits usable tiers.',
'terrace_width':'1–8 m base width; varies coherently over space.',
'silhouette_irregularity':'0–1 edge warp from coherent noise; changes shelf boundaries without disconnected vertices.',
'facet_variation':'0–1 restrained cap grain and seeded coarse cell-diagonal changes. No extra triangles.',
'rock_debris_density':'0–3 acceptance multiplier for rock/debris candidates; not a guaranteed count.',
'floor_vegetation':'0–3 acceptance multiplier on clear canyon floor.',
'base_vegetation':'0–3 acceptance multiplier near cliff bases.',
'terrace_vegetation':'0–3 acceptance multiplier on intermediate shelves.',
'plateau_vegetation':'0–3 acceptance multiplier on upper terrain.',
'decorative_extent':'0–35 m detailed exterior treatment. Farther terrain fades to a lower profile; does not enlarge the canonical field.',
'candidates_per_room':'0–1000 attempts per room per density phase. Support, water, route and spacing tests reject candidates.',
'maximum_decorations':'0–6000 hard candidate cap across the map, including the optional extra-vegetation phase. Renderer can reject more.'}
configrows=''.join(f'<tr><td><code>{k}</code></td><td>{v}</td><td>{explanations[k]}</td></tr>' for k,v in config)
changed=['src/world/CanyonAppearance.hpp','src/world/CanyonAppearance.cpp','assets/visual/canyon.cfg','assets/visual/canyon-legacy.cfg','src/render/CanyonScene.cpp','src/render/WesternScene.cpp','src/render/WesternScene.hpp','CMakeLists.txt','tests/canyon_appearance_tests.cpp','tests/western_assets_tests.cpp','tests/occlusion_tests.cpp','README.md','scripts/canyon-terraces-report.py']
files=''.join(f'<li><a href="../../../{p}">{p}</a></li>' for p in changed)
doc='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>DeathWard · Canyon terraces</title><style>
:root{color-scheme:dark;--ink:#ede5d5;--muted:#bcb3a5;--panel:#25292a;--accent:#eeb36e}*{box-sizing:border-box}body{margin:0;background:#171b1d;color:var(--ink);font:16px/1.65 system-ui,sans-serif}main{max-width:1500px;margin:auto;padding:36px 4vw 80px}h1{font-size:clamp(30px,4vw,56px);line-height:1.1;margin:12px 0 24px}h2{margin-top:44px;color:var(--accent)}h3{margin:0 0 14px}p{max-width:1100px}a{color:#9bd8c5}code,pre{font:14px/1.6 ui-monospace,monospace}code{overflow-wrap:anywhere}pre{background:#0e1213;padding:18px;overflow:auto;border-radius:8px}.eyebrow{letter-spacing:.12em;text-transform:uppercase;color:var(--accent)}.lead{font-size:20px}.note{border-left:3px solid var(--accent);padding:12px 20px;background:var(--panel)}.metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:16px;margin:24px 0}.metric{padding:18px;background:var(--panel);border-radius:8px}.metric strong{font-size:26px;display:block;color:var(--accent)}.metric span{color:var(--muted)}article{margin:24px 0 38px;padding:20px;background:var(--panel);border-radius:10px}.compare{position:relative;overflow:hidden;width:100%;aspect-ratio:1440/900;background:#111}.compare img{display:block;width:100%;height:100%;object-fit:cover}.before{position:absolute;inset:0;clip-path:inset(0 calc(100% - var(--split)) 0 0)}.old,.new{position:absolute;top:10px;background:#101717db;padding:5px 10px;border-radius:4px}.old{left:10px}.new{right:10px}.divider{position:absolute;top:0;bottom:0;left:var(--split);width:2px;background:#fff9;pointer-events:none}.slider{display:flex;align-items:center;gap:20px;margin:12px 0}.slider input{width:min(600px,65%);accent-color:var(--accent)}table{border-collapse:collapse;width:100%;margin:16px 0;font-variant-numeric:tabular-nums}td,th{padding:10px;text-align:left;border-bottom:1px solid #ffffff20;vertical-align:top}th{color:var(--accent)}.scroll{overflow:auto}.reference{max-width:950px;width:100%;display:block}.small{font-size:14px;color:var(--muted)}li{margin:8px 0}details{background:var(--panel);padding:18px;border-radius:8px;margin:18px 0}summary{cursor:pointer;color:var(--accent)}@media(max-width:650px){main{padding:20px 16px}article{padding:10px}td,th{padding:8px;font-size:13px}.old,.new{font-size:12px}.slider{font-size:13px;gap:10px}}
</style><main><div class="eyebrow">DeathWard · Procedural expedition scenery · 1 November 2026</div><h1>Lower canyons.<br>Visible shelves. Preserved encounters.</h1>
<p class="lead">A reversible canyon rendering treatment: lower seeded sandstone tiers, varied low-poly facets, and terrain-aware cosmetic dressing. The existing room graph and authoritative collision terrain remain unchanged.</p>
<p>Baseline: commit <code>7e565fe</code>. Only the supplied target Image B was available. The original build was captured before editing; these comparisons use matching scripted scenes and camera settings, rather than pretending to recreate the target image’s unknown seed and player position.</p>
<div class="metrics"><div class="metric"><strong>7.56 → 4.52 m</strong><span>median highland vertex height across 12 maps</span></div><div class="metric"><strong>0 added triangles</strong><span>same lattice, two triangles per cell</span></div><div class="metric"><strong>12 seeded maps</strong><span>dry, boundary river and interior river coverage</span></div><div class="metric"><strong>5 gameplay suites pass</strong><span>plus visual geometry and graphics checks</span></div></div>
<p class="note"><b>Important limitation:</b> this is a cosmetic terrain copy. Navigation, flying-enemy placement and projectile collision still use the original taller terrain. A shot above a lowered visual ledge can therefore meet the old invisible rock volume. Changing those physical volumes would change gameplay and was deliberately excluded from this task. Terrace tops and decorative exterior terrain remain inaccessible.</p>
<h2>Matched before / after captures</h2><p>Drag each slider. Both sides use seed 1866, Original style, 1440 × 900, 160% zoom, perspective projection with the existing 45° field of view, and frame 120. Camera tracking, player controls, UI and combat behavior are unchanged. Scripted scenarios grant items and spawn encounters; their HUD is the existing test setup. Capture FPS labels are incidental snapshots, not the performance comparison.</p>'''+cards+'''
<details><summary>Supplied visual target and honest visual assessment</summary><img class="reference" src="reference-target.png" alt="User-supplied target canyon concept"><p>The new geometry exposes more upper terrain and replaces much of the tall continuous face with stepped shelves. Shared vertices avoid chunk cracks. Existing interior cover remains distinct; roads and river/ford locations remain recognizable. Debris and grasses now occupy floor, base, shelf and plateau categories.</p><p>The result is still coarser and less lush than the concept. The preserved 1.25 m lattice limits small ledges and silhouette detail. This pass reuses the packaged grass, cactus and rock models; it does not supply new desert-tree or true agave assets. Counts are intentionally bounded and density remains tunable. Matching the concept’s exact vegetation richness and art direction requires visual review, not just passing tests.</p></details>
<h2>Architecture: before and after</h2><div class="scroll"><table><tr><th>System</th><th>Existing responsibility</th><th>This change</th></tr>
<tr><td>Dungeon.cpp / RoomGraph</td><td>Seeded connected rooms, doors, sockets, encounter state and traversal.</td><td>Unmodified. Expeditions retain their floors and connected locked combat rooms.</td></tr>
<tr><td>CanyonTerrain.cpp</td><td>A shared 1.25 m height lattice from room outlines and outcrops. A 40 m exterior margin, extended for boundary rivers. The same field drives collision, path checks and projectile traces.</td><td>Canonical field is unmodified. It remains the gameplay authority.</td></tr>
<tr><td>CanyonRiver.cpp / CanyonRoad.cpp</td><td>Boundary rivers, interior crossings and fords, plus connected interior dirt roads.</td><td>Unmodified. Low floor, water and ford vertices at or below 0.2 m retain their exact heights.</td></tr>
<tr><td>New CanyonAppearance module</td><td>No previous separate art-direction field.</td><td>Copies canonical terrain, computes distance-to-floor and distance-to-rock, coherent cap/edge variation, shelf bands and candidate decoration zones. Uses an independent visual seed stream; never consumes gameplay RNG.</td></tr>
<tr><td>CanyonScene.cpp</td><td>Two triangles per cell, spatial terrain chunks, atlas materials, shadows, wall fading and scenery picking.</td><td>Builds the same-size mesh from the cosmetic field, using shared vertices and seeded diagonal variation. Visual ray sampling, fading and picking follow the actual rendered triangles.</td></tr>
<tr><td>WesternScene.cpp</td><td>Existing packaged models, material instancing, decoration density, visibility and cached scene rebuilds.</td><td>Places the new cosmetic candidates instead of the old canyon dressing path. Mine and legacy canyon generation keep their existing paths. No new asset dependencies.</td></tr>
<tr><td>Lighting and materials</td><td>Existing ground treatment, sandstone cap/face atlas swatches, directional shadows and post-processing.</td><td>Retained. Lower geometry already changes shading and visible horizontal surfaces; no lighting rewrite or grading change is needed to evaluate geometry.</td></tr></table></div>
<h2>Generation and decoration rules</h2><p>Broad coherent noise sets local cap height; distance from the original floor sets tier progression. Spatially varying shelf width and restrained edge warp break up uniform bands. Grain and coarse seeded diagonal choices vary facets without adding triangles. The original height provides an upper bound, preserving existing low outcrops. Far terrain is retained with a lower profile beyond the configured detailed extent.</p>
<div class="scroll"><table><tr><th>Category</th><th>Dressing</th><th>Placement constraints</th></tr><tr><td>Canyon floor</td><td>Sparse grasses, bushy grass clumps and small stones.</td><td>Protect central encounter/objective space, roads, shoulders, entrances, exits, keys, supplies and existing props.</td></tr><tr><td>Cliff base</td><td>Higher debris preference, dry vegetation and occasional fallen sticks.</td><td>Require dry supported ground, reject overlap and route reservations.</td></tr><tr><td>Intermediate shelf</td><td>Grass clumps, shrub-like grasses and rocks.</td><td>Whole-footprint support samples reject steep faces.</td></tr><tr><td>Plateau</td><td>Grass, larger clumps, rocks and occasional cactus.</td><td>Cacti use stricter support checks with a safety margin; no cacti on slopes.</td></tr></table></div>
<p>All new props are cosmetic: they do not register collision or intercept aiming. Existing render batching by asset/material is reused. Two independent candidate phases preserve the global 0–200% vegetation control: increasing density retains already-present plants and enables the extra phase. Rock/debris counts do not follow that vegetation slider.</p>
<h2>Configuration and rollback</h2><p>Edit <a href="../../../assets/visual/canyon.cfg"><code>assets/visual/canyon.cfg</code></a> and restart the game. The configuration is loaded when canyon terrain is prepared; it does not hot reload an already cached scene. The native build copies it to <code>build/assets/visual/</code> beside the executable. When using a packaged build, edit that runtime copy. Unknown, duplicate, malformed and out-of-range values are rejected.</p>
<pre># Default new visuals
./build/deathward

# Restore the original canyon geometry AND original decoration paths
DEATHWARD_CANYON_CONFIG=assets/visual/canyon-legacy.cfg ./build/deathward

# Alternatively: set enabled 0 in the runtime canyon.cfg and restart.</pre>
<p><a href="legacy-restored.png">Rollback capture, same combat scene</a> · <a href="legacy-restored.log">Rollback log</a>. The legacy switch restores the original generation paths. In this same-size capture, outside the FPS label, only 0.035% of color channels differ from the untouched baseline and the maximum delta is 2/255.</p>
<div class="scroll"><table><tr><th>Parameter</th><th>Default</th><th>Meaning / valid range</th></tr>'''+configrows+'''</table></div>
<h2>Regression results</h2><div class="scroll"><table><tr><th>Check</th><th>Result and scope</th><th>Evidence</th></tr><tr><td>Visual geometry</td><td>PASS: 12 maps across six seeds, river off/on; all three river categories. Deterministic vertices, props and categories. Same lattice size and walkability signs, unchanged canonical terrain hash, floor cells, boundary heights, collision and sample projectile traces. 180 room collision checks; invalid configuration rejection, density isolation and rollback.</td><td><a href="geometry-tests.log">Log</a></td></tr><tr><td>Gameplay regression</td><td>PASS: floor_progression, canyon_roads, canyon_rivers, generated_dungeons, generated_room_graphs. Existing tests cover seeded connectivity, doors/combat locks, backtracking, room types, roads, river crossings and floor progression. These are automated checks, not an exhaustive manual playthrough.</td><td><a href="gameplay-regressions.log">5-suite log</a></td></tr><tr><td>GPU assets and mesh sampling</td><td>PASS: 15,661 placement observations across five seeds and both themes, including density changes. Mesh height/rays match cosmetic terrain, supported cacti, clear routes, deterministic restores and texture/material/resource checks.</td><td><a href="graphics-assets-tests.log">Log</a></td></tr><tr><td>GPU occlusion and actual input</td><td>PASS: all three hubs, canyon/wide view, player fading, three hidden enemy types, absent-body/friendly suppression, resident animation, left/right/Shift aiming, rotated camera and real projectile cover. Canyon hide-target fixtures use a lower test-only camera because lower cliffs no longer obscure those targets at the normal angle. Production camera unchanged. Fixtures now use the same map for the obstruction and flying enemy.</td><td><a href="occlusion-tests.log">Full log</a></td></tr><tr><td>Build and scope</td><td>Native Linux build passes. No camera/UI/AI/combat/gameplay-generation source changes. WASM checks omitted under the standing user waiver; config assets are registered for packaging.</td><td><a href="native-build.log">Native build log</a> · <a href="measurements.json">Measurements</a></td></tr></table></div>
<h2>Performance comparison</h2><p>Three alternating pairs using the same final native executable: legacy config, then default terraces. Seed 1866; 1440 × 900; 240 uncapped stress frames. No other graphics tests or builds run concurrently. The benchmark intentionally maintains hundreds of enemies/projectiles and resets scenarios; it is not representative of ordinary gameplay FPS. The table reports medians of the three run-level measurements, in milliseconds. A lower value is better.</p><div class="scroll"><table><tr><th>Measurement</th><th>Legacy median (ms)</th><th>Terraced median (ms)</th><th>Change</th></tr>'''+rows+'''</table></div>
<p>The measured combat scene retains 113,388 terrain/underlay triangles and 105 terrain chunks. At 100% vegetation, total scenery instances change from 198 to 368 (vegetation 68 to 144). Terrain triangle count stays constant. Instance counts can change with terrain support, category densities and visibility. One-time CPU preparation averages 58.9 ms across the 12 geometry-test maps; it is not a per-frame cost. WSL presentation timing is variable, so these are local observations rather than a hardware-independent performance claim.</p><p><a href="paired-legacy-1.log">Legacy 1</a> · <a href="paired-legacy-2.log">Legacy 2</a> · <a href="paired-legacy-3.log">Legacy 3</a> · <a href="after-benchmark-1.log">Terraced 1</a> · <a href="after-benchmark-2.log">Terraced 2</a> · <a href="after-benchmark-3.log">Terraced 3</a> · <a href="measurements.json">Raw parsed results</a></p>
<p class="small">The earlier before-benchmark-*.log files retain measurements from the untouched baseline executable. They were recorded during development and are not used for the final controlled paired comparison.</p>
<p>The median mean-frame result improves about 5.7%, while p95 worsens about 2.9%; this is mixed performance evidence, not a claim that every frame is faster. All six runs have identical reported simulation workload counters.</p><h2>Reproduce</h2><pre>cmake --build build --target deathward deathward_canyon_appearance_tests -j4
./build/deathward_canyon_appearance_tests
ctest --test-dir build --output-on-failure \\
  -R '^(floor_progression|canyon_roads|canyon_rivers|generated_dungeons|generated_room_graphs)$'
./build/deathward_western_assets_tests
./build/deathward_occlusion_tests

# Screenshot (repeat with profile-quarry and profile-works)
./build/deathward --mute --smoke --style original --theme canyon \\
  --scene combat --frames 120 --screenshot /tmp/canyon.png

# Stress benchmark; repeat with the legacy environment variable above
./build/deathward --mute --benchmark --theme canyon --frames 240</pre>
<h2>Changed files and remaining work</h2><ul>'''+files+'''<li>This report, measurements, unmodified PNG captures, reference and test logs in <code>docs/reports/canyon-terraces/</code>.</li></ul>
<p>Remaining: user visual review and tuning of shelf shapes/density against the target. This is an initial art-direction implementation, not a claim of pixel-perfect concept fidelity. No new desert trees, true agave models or new material/lighting treatment were added. A future decision to align lowered visual cliff tops with physical shot/flying volumes requires a separate gameplay change and regression pass. Existing room boundaries and canonical collision remain intact in this implementation.</p>
<p class="small">All evidence is local and viewable offline. Screenshot PNGs are kept individually for direct inspection and sharing.</p></main><script>document.querySelectorAll('.slider input').forEach(e=>e.addEventListener('input',()=>e.closest('article').querySelector('.compare').style.setProperty('--split',e.value+'%')));</script></html>'''
(r/'index.html').write_text(doc)
print('Built report; benchmark runs:', {k:len(v) for k,v in bench.items()})
